      const imageData = {
        title: "Northern Aurora",
        description: "A cinematic long-exposure capture preserved in your personal library.",
        resolution: "3840 x 2160",
        size: "12.4 MB",
        type: "RAW Photo",
        added: "May 5, 2026",
      };

      function ModalDialog() {
        return `
          <div class="dialog-backdrop" ${state.isDialogOpen ? "" : "hidden"} data-backdrop>
            <div
              class="dialog"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
            >
              <div class="dialog-icon" aria-hidden="true">!</div>
              <h2 id="dialog-title">Delete image?</h2>
              <p id="dialog-description">
