              </p>
              <div class="dialog-actions">
                <button type="button" class="ghost-action" data-action="close">Cancel</button>
                <button type="button" class="danger-action" data-action="confirm-delete">Delete image</button>
              </div>
            </div>
          </div>
        `;
      }

      function ImagePreview() {
        return `
          <main class="preview-page">
            <section class="hero">
              <div class="image-frame">
                <div class="image-card" role="img" aria-label="${imageData.title} image preview"></div>
              </div>
              <aside class="details">
                <div>
                  <p class="eyebrow">Image library</p>
                  <h1>${imageData.title}</h1>
                  <p class="description">${imageData.description}</p>
                </div>

                <ul class="meta">
                  <li><span class="meta-label">Resolution</span><span class="meta-value">${imageData.resolution}</span></li>
                  <li><span class="meta-label">File size</span><span class="meta-value">${imageData.size}</span></li>
                  <li><span class="meta-label">Format</span><span class="meta-value">${imageData.type}</span></li>
                  <li><span class="meta-label">Added</span><span class="meta-value">${imageData.added}</span></li>
                </ul>

                <div>
                  <div class="actions">
                    <button type="button" class="secondary-action">Download</button>
                    <button type="button" class="trigger" data-action="open-dialog">Delete from library</button>
                  </div>
                  <div class="status" aria-live="polite">
                    ${state.isDeleted ? `${imageData.title} was removed from your library.` : ""}
                  </div>
                </div>
              </aside>
            </section>
          </main>
        `;
      }

      function App() {
        return `
          <div class="app-shell">
            ${ImagePreview()}
            ${ModalDialog()}
          </div>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
      }

      document.addEventListener("click", (event) => {
        const actionTarget = event.target.closest("[data-action]");
        const clickedBackdrop = event.target.matches("[data-backdrop]");

        if (clickedBackdrop) {
          state.isDialogOpen = false;
          render();
          return;
        }

        if (!actionTarget) {
          return;
        }

        const { action } = actionTarget.dataset;

        if (action === "open-dialog") {
          state.isDialogOpen = true;
        } else if (action === "close") {
          state.isDialogOpen = false;
        } else if (action === "confirm-delete") {
          state.isDialogOpen = false;
          state.isDeleted = true;
        }

        render();
      });

      document.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && state.isDialogOpen) {
          state.isDialogOpen = false;
          render();
        }
      });

      render();
    </script>
